    assert_eq!(h.app.session.catalog.photo(id).unwrap().meta.regions[0].name, None);
    // open it again, type a name, Enter: the face is named, in one undo step
    h.request("ui.pointer", json!({"events": [{"kind": "move", "x": 0.42, "y": 0.4}]}), t);
    h.step();
