    assert_eq!(r["ok"], true, "{r}");
    assert_eq!(h.app.session.visible_cloned().len(), 2);
    h.app.ui.dialog = Some(crate::state::Dialog::RenameKeyword { from: "travel".into(), to: "trips".into() });
    h.settle(SETTLE);
